import{_ as e,o,c as a,ag as n}from"./chunks/plugin-vue_export-helper.BT7B-090.js";const d=JSON.parse('{"title":"пиар и наука переплетаются в одну вонючую косичку","description":"","frontmatter":{"site":"pro","title":"пиар и наука переплетаются в одну вонючую косичку","date":"2026-10-31T00:00:00.000Z","source":"https://t.me/jfyi_ps/121","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-31-piar-i-nauka-perepletayutsya-v-odnu-vonyuchuyu"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"пиар и наука переплетаются в одну вонючую косичку"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-31-piar-i-nauka-perepletayutsya-v-odnu-vonyuchuyu"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"пиар и наука переплетаются в одну вонючую косичку"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"пиар и наука переплетаются в одну вонючую косичку\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-31-piar-i-nauka-perepletayutsya-v-odnu-vonyuchuyu\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-31\\"}"]]},"headers":[],"relativePath":"posts/2026-10-31-piar-i-nauka-perepletayutsya-v-odnu-vonyuchuyu.md","filePath":"posts/2026-10-31-piar-i-nauka-perepletayutsya-v-odnu-vonyuchuyu.md"}'),p={name:"posts/2026-10-31-piar-i-nauka-perepletayutsya-v-odnu-vonyuchuyu.md"};function r(i,t,u,s,c,l){return o(),a("div",null,[...t[0]||(t[0]=[n("<p>OpenAI на этой неделе заявила, что её искусственный интеллект опроверг ETH - гипотезу, на которой 30 лет стояла половина теоретической информатики. Заодно, по словам компании, тот же ИИ разобрался с гипотезой Какии во всех размерностях и доказал существование квантовой теории Янга - Миллса в четырёхмерном пространстве.</p><p>Три фундаментальные проблемы за один пресс-релиз.</p><p>С одной стороны, если это правда - человечество только что переписало учебники по трём дисциплинам сразу. Тектонический сдвиг. К тому же Anthropic поддакнула, правда, нашла совсем другой алгоритм.</p><p>С другой стороны - где пруфы?</p><p>OpenAI не вывалила доказательсво в блог. Она передала его в MIT, а внешний эксперт Райян Уильямс собрал команду, включая самих авторов ETH - Импальяццо и Патури. Первые версии текста, по словам Импальяццо, были “полностью нечитаемыми”. То есть компания, которая кричит о прорыве, сначала выдала на-гора кусок кода, который даже математики не смогли продрать с первого раза. Это как показать палец и сказать: “Там Луна”. Формально не придраться, но и не объяснишь.</p><p>Проверять ETH будет не OpenAI, а математическое сообщество. Пока суд да дело, любой аспирант может заезть на GitHub, где лежит часть выкладок, и попробовать найти дырку.</p><p>А теперь главное. Вся эта история - не про то, что ИИ стал умнее человека. Она про то, что с каждой такой новостью часть сообщетсва хватается за сердце, часть - за кошелёк, а нормальным пацанам остается только сидеть и ждать, пока кто-нибудь не проверит код.</p><p>Если это не хайп - мы живём в интересное время, когда спрос на научное рецензирование возрос в разы. А если хайп - значит большая часть новостной повестки про научные прорывы - хорошо упакованный маркетинг.</p><p>Я и сам жду когда моя статья пройдёт рецензирование и будет опубликована. Исследование опровергает доходность 46 стратегий трейдинга и обличает AlgoPack в регенерации данных, что вызывает падение качества прогноза на 60%. То есть, на этих данных доходность прогнозируется, а на реальных - нет.</p><p>Это время интересно ещё и тем, что от исследования до публикации проходит в среднем полгода, а значит общаться с исследователями напрямую гораздо интереснее, чем читать научные журналы.</p>",10)])])}const m=e(p,[["render",r]]);export{d as __pageData,m as default};
